using System;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static async Task Wait50() { await Task.Delay(50); }   // no thread is held while waiting

    static void Main()
    {
        int before = Process.GetCurrentProcess().Threads.Count;
        var sw = Stopwatch.StartNew();
        // 500 concurrent "operations": each is a timer, not a thread
        Task[] tasks = Enumerable.Range(0, 500).Select(i => Wait50()).ToArray();
        Task.WaitAll(tasks);
        sw.Stop();
        int after = Process.GetCurrentProcess().Threads.Count;
        Console.WriteLine("Tasks completed: " + tasks.Count(t => t.IsCompletedSuccessfully_()));
        Console.WriteLine("Finished well under 500*50ms=25s: " + (sw.ElapsedMilliseconds < 5000));
        // 500 real threads would add ~500; tasks add only a few pool threads
        Console.WriteLine("Extra OS threads far below 500: " + ((after - before) < 100));
    }
}

static class Ext
{
    public static bool IsCompletedSuccessfully_(this Task t) { return t.Status == TaskStatus.RanToCompletion; }
}

using System;
using System.Threading.Tasks;

// Hand-written version of what the compiler does for:
//   async Task<int> Work() { Console.WriteLine("start"); await Task.Delay(20); return 42; }
class WorkMachine
{
    int state = 0;                                   // which await we are at
    TaskCompletionSource<int> builder = new TaskCompletionSource<int>(); // plays the AsyncTaskMethodBuilder
    Task delay;

    public Task<int> Start() { MoveNext(); return builder.Task; }

    void MoveNext()
    {
        if (state == 0)
        {
            Console.WriteLine("state 0: start");
            delay = Task.Delay(20);
            if (!delay.IsCompleted)
            {
                state = 1;                            // remember where to resume
                delay.ContinueWith(t => MoveNext());  // register MoveNext as the continuation
                return;                               // caller gets the incomplete Task
            }
        }
        if (state == 1 || state == 0)
        {
            Console.WriteLine("state 1: resumed after await");
            builder.SetResult(42);                    // completes the returned Task
        }
    }
}

class Program
{
    static void Main()
    {
        Task<int> t = new WorkMachine().Start();
        Console.WriteLine("back in caller, task completed yet? " + t.IsCompleted);
        Console.WriteLine("result = " + t.Result);
    }
}

