// A single-threaded context, like a UI thread: all posted work runs on ONE thread.
class OneThreadContext : SynchronizationContext
{
    BlockingCollection<Action> queue = new BlockingCollection<Action>();
    public override void Post(SendOrPostCallback d, object s) { queue.Add(() => d(s)); }
    public void RunLoop() { foreach (var a in queue.GetConsumingEnumerable()) a(); }
}

class Program
{
    static async Task<int> LoadAsync() { await Task.Delay(20); return 7; }
    static async Task<int> LoadLibAsync() { await Task.Delay(20).ConfigureAwait(false); return 7; }

    static void Main()
    {
        var ctx = new OneThreadContext();
        var done = new ManualResetEventSlim();
        var ui = new Thread(() =>
        {
            SynchronizationContext.SetSynchronizationContext(ctx);
            ctx.Post(_ =>
            {
                // blocking on the context thread: continuation needs this same thread
                bool ok1 = LoadAsync().Wait(500);
                Console.WriteLine("Blocking .Wait on captured context finished: " + ok1);
                // ConfigureAwait(false): continuation runs on the pool, no deadlock
                bool ok2 = LoadLibAsync().Wait(500);
                Console.WriteLine("Blocking .Wait with ConfigureAwait(false) finished: " + ok2);
                done.Set();
            }, null);
            ctx.RunLoop();
        });
        ui.IsBackground = true;
        ui.Start();
        done.Wait();
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

// Counts how many continuations had to be posted back to the context.
class CountingContext : SynchronizationContext
{
    public int Posts;
    public override void Post(SendOrPostCallback d, object s)
    {
        Interlocked.Increment(ref Posts);
        ThreadPool.QueueUserWorkItem(_ => { SetSynchronizationContext(this); d(s); });
    }
}

class Program
{
    static async Task Capture() { await Task.Delay(10); await Task.Delay(10); }
    static async Task Library() { await Task.Delay(10).ConfigureAwait(false); await Task.Delay(10).ConfigureAwait(false); }

    static void Main()
    {
        var ctx = new CountingContext();
        SynchronizationContext.SetSynchronizationContext(ctx);
        Capture().Wait();
        Console.WriteLine("Default awaits, posts to context: " + ctx.Posts);

        ctx = new CountingContext();
        SynchronizationContext.SetSynchronizationContext(ctx);
        Library().Wait();
        Console.WriteLine("ConfigureAwait(false) awaits, posts to context: " + ctx.Posts);
        // An already-completed task never switches, even with the default setting
        ctx = new CountingContext();
        SynchronizationContext.SetSynchronizationContext(ctx);
        Task.FromResult(1).GetAwaiter().GetResult();
        Console.WriteLine("Completed task, posts: " + ctx.Posts);
    }
}

using System;
using System.Threading.Tasks;

class Program
{
    static async Task Fail(string msg, int ms)
    {
        await Task.Delay(ms);
        throw new InvalidOperationException(msg);
    }

    static void Main() { Run().GetAwaiter().GetResult(); }

    static async Task Run()
    {
        Task a = Fail("A failed", 10), b = Fail("B failed", 40), c = Task.Delay(60);
        Task all = Task.WhenAll(a, b, c);            // keep the combined task
        try { await all; }
        catch (Exception e) { Console.WriteLine("await rethrew only: " + e.Message); }
        Console.WriteLine("Status: " + all.Status);
        foreach (var inner in all.Exception.InnerExceptions)    // every failure is here
            Console.WriteLine("  inner: " + inner.Message);

        Task d = Fail("D failed", 10), e2 = Task.Delay(500);
        Task first = await Task.WhenAny(d, e2);      // WhenAny itself never faults
        Console.WriteLine("WhenAny returned the faulted task: " + (first == d) + ", " + first.Status);
        try { await first; } catch (Exception e) { Console.WriteLine("observed on await: " + e.Message); }
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static async Task Work(CancellationToken ct)
    {
        for (int i = 1; i <= 100; i++)
        {
            ct.ThrowIfCancellationRequested();      // cooperative check at a safe point
            await Task.Delay(20, ct);               // passing the token aborts the wait early
        }
    }

    static void Main()
    {
        using (var cts = new CancellationTokenSource())
        {
            cts.CancelAfter(100);                   // request cancel after 100 ms
            Task t = Work(cts.Token);
            try { t.Wait(); }
            catch (AggregateException ex)
            {
                Console.WriteLine("Exception type: " + ex.InnerException.GetType().Name);
            }
            Console.WriteLine("Task status: " + t.Status);
        }
        // Linked source: caller token OR own timeout
        var caller = new CancellationTokenSource();
        using (var linked = CancellationTokenSource.CreateLinkedTokenSource(caller.Token))
        {
            caller.Cancel();
            Console.WriteLine("Linked token cancelled by caller: " + linked.Token.IsCancellationRequested);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Threading.Tasks;

class Program
{
    static Dictionary<int, string> cache = new Dictionary<int, string> { { 1, "cached-one" } };

    // Hit: no Task allocated. Miss: falls back to a real Task.
    static ValueTask<string> GetAsync(int id)
    {
        string v;
        if (cache.TryGetValue(id, out v)) return new ValueTask<string>(v);
        return new ValueTask<string>(LoadSlow(id));
    }

    static async Task<string> LoadSlow(int id)
    {
        await Task.Delay(20);
        cache[id] = "loaded-" + id;
        return cache[id];
    }

    static void Main() { Run().GetAwaiter().GetResult(); }

    static async Task Run()
    {
        ValueTask<string> hit = GetAsync(1);
        Console.WriteLine("hit completed synchronously: " + hit.IsCompleted);
        Console.WriteLine(await hit);               // await exactly once

        ValueTask<string> miss = GetAsync(2);
        Console.WriteLine("miss completed synchronously: " + miss.IsCompleted);
        Task<string> task = miss.AsTask();          // rule: AsTask() if you need a Task (use once)
        Console.WriteLine(await task);
        Console.WriteLine(await task);              // a Task can be awaited many times; a ValueTask must not
    }
}

using System;
using System.Threading.Tasks;

// Hand-made async stream: items are fetched only when the consumer asks (pull-based).
class PageStream
{
    int page = 0;
    public int Fetched;
    public string Current;

    public async Task<bool> MoveNextAsync()
    {
        if (page >= 5) return false;
        await Task.Delay(10);                       // simulate a network call for one page
        page++; Fetched++;
        Current = "page-" + page;
        return true;
    }
}

class Program
{
    static void Main() { Run().GetAwaiter().GetResult(); }

    static async Task Run()
    {
        var s = new PageStream();
        // same shape as: await foreach (var p in GetPages()) { ... }
        while (await s.MoveNextAsync())
        {
            Console.WriteLine("got " + s.Current);
            if (s.Current == "page-2") break;       // stop early: remaining pages never fetched
        }
        Console.WriteLine("pages fetched: " + s.Fetched + " of 5");
    }
}

using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int running = 0, maxSeen = 0;

    static async Task Call(int id, SemaphoreSlim gate)
    {
        await gate.WaitAsync();                      // wait for a free slot
        try
        {
            int now = Interlocked.Increment(ref running);
            int m;
            while (now > (m = maxSeen)) Interlocked.CompareExchange(ref maxSeen, now, m);
            await Task.Delay(30);                    // the "remote call"
            Interlocked.Decrement(ref running);
        }
        finally { gate.Release(); }                  // always give the slot back
    }

    static void Main()
    {
        var gate = new SemaphoreSlim(3);
        Task[] all = Enumerable.Range(1, 12).Select(i => Call(i, gate)).ToArray();
        Task.WaitAll(all);
        Console.WriteLine("operations: 12, limit: 3");
        Console.WriteLine("max running at once: " + maxSeen);
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static readonly object gate = new object();

    static void Test(bool async_)
    {
        var tcs = async_
            ? new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously)
            : new TaskCompletionSource<int>();
        bool ranInsideLock = false;
        var seen = new ManualResetEventSlim();
        // continuation registered like an awaiting consumer would
        tcs.Task.ContinueWith(t =>
        {
            ranInsideLock = Monitor.IsEntered(gate);  // are we still inside the producer's lock?
            seen.Set();
        }, async_ ? TaskContinuationOptions.RunContinuationsAsynchronously : TaskContinuationOptions.ExecuteSynchronously);
        lock (gate) { tcs.SetResult(1); }           // producer completes while holding a lock
        seen.Wait();
        Console.WriteLine("RunContinuationsAsynchronously=" + async_ + " -> consumer ran inside producer's lock: " + ranInsideLock);
    }

    static void Main()
    {
        Test(false);
        Test(true);
    }
}

