using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

// A tiny pool with a fixed number of threads, so starvation is easy to see.
class FixedPool : TaskScheduler
{
    BlockingCollection<Task> q = new BlockingCollection<Task>();
    public FixedPool(int n)
    {
        for (int i = 0; i < n; i++)
        {
            var t = new Thread(() => { foreach (var task in q.GetConsumingEnumerable()) TryExecuteTask(task); });
            t.IsBackground = true; t.Start();
        }
    }
    protected override void QueueTask(Task t) { q.Add(t); }
    protected override bool TryExecuteTaskInline(Task t, bool w) { return false; }
    protected override System.Collections.Generic.IEnumerable<Task> GetScheduledTasks() { return q.ToArray(); }
}

class Program
{
    static bool Run(int threads)
    {
        var pool = new FixedPool(threads);
        var f = new TaskFactory(pool);
        Task<int>[] outer = new Task<int>[2];
        for (int i = 0; i < 2; i++)
            outer[i] = f.StartNew(() =>
            {
                Task<int> inner = f.StartNew(() => 1);   // needs a free pool thread
                return inner.Result;                      // blocks this pool thread: sync-over-async
            });
        return Task.WaitAll(new Task[] { outer[0], outer[1] }, 500);
    }

    static void Main()
    {
        Console.WriteLine("2 threads, 2 blocking tasks finished: " + Run(2));   // starved
        Console.WriteLine("4 threads, 2 blocking tasks finished: " + Run(4));   // enough spare threads
    }
}

using System;
using System.Threading.Tasks;

class Program
{
    static async Task F()
    {
        Console.WriteLine("A");
        await Task.Delay(1);                         // incomplete -> F returns here
        Console.WriteLine("C");
    }

    static async Task G()
    {
        Console.WriteLine("A");
        await Task.CompletedTask;                    // already complete -> no suspension
        Console.WriteLine("C");
    }

    static void Main() { Run().GetAwaiter().GetResult(); }

    static async Task Run()
    {
        Console.WriteLine("-- F with Task.Delay(1):");
        var t = F();
        Console.WriteLine("B");
        await t;
        Console.WriteLine("-- G with Task.CompletedTask:");
        var u = G();
        Console.WriteLine("B");
        await u;
    }
}

using System;
using System.Threading.Tasks;

class Program
{
    // Lazy: the throw is captured in the returned task
    static async Task<int> LazyAsync(string path)
    {
        if (path == null) throw new ArgumentNullException("path");
        await Task.Delay(1);
        return path.Length;
    }

    // Eager: plain method validates, then calls the async part
    static Task<int> EagerAsync(string path)
    {
        if (path == null) throw new ArgumentNullException("path");
        return Core(path);
    }
    static async Task<int> Core(string path) { await Task.Delay(1); return path.Length; }

    static void Main()
    {
        try
        {
            Task<int> t = LazyAsync(null);
            Console.WriteLine("Lazy: call returned, no exception yet. Status = " + t.Status);
            t.Wait();
        }
        catch (AggregateException e) { Console.WriteLine("Lazy: surfaced only on Wait: " + e.InnerException.GetType().Name); }

        try { EagerAsync(null); Console.WriteLine("Eager: no exception"); }
        catch (ArgumentNullException) { Console.WriteLine("Eager: threw at the call site"); }
    }
}

using System;
using System.Threading.Tasks;

class Program
{
    static bool finished = false;

    static void Main() { Run().GetAwaiter().GetResult(); }

    static async Task Run()
    {
        Func<Task> work = async () => { await Task.Delay(100); finished = true; };

        // StartNew returns Task<Task>: the outer task ends at the first await
        Task<Task> outer = Task.Factory.StartNew(work);
        await outer;
        Console.WriteLine("StartNew: awaited once, work finished? " + finished);
        await outer.Result;                           // need Unwrap() or a second await
        Console.WriteLine("StartNew: after awaiting the inner task, finished? " + finished);

        finished = false;
        await Task.Run(work);                         // Task.Run unwraps for you
        Console.WriteLine("Task.Run: awaited once, work finished? " + finished);
    }
}
